shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/src/acl.c
+++ b/src/acl.c
@@ -2378,6 +2378,8 @@
         listRewind(server.clients, &li);
         while ((ln = listNext(&li)) != NULL) {
             client *c = listNodeValue(ln);
+            /* The primary connection has no user and is not subject to ACL rules. */
+            if (!c->user) continue;
             user *original = c->user;
             list *channels = NULL;
             user *new_user = ACLGetUserByName(c->user->name, sdslen(c->user->name));
PATCH
make -j4 > /tmp/valkey-acl-build.log 2>&1 && ./runtest --single unit/acl --only 'ACL LOAD on a replica preserves the primary connection' > /tmp/valkey-acl-regression-after.log 2>&1; result=$?; tail -25 /tmp/valkey-acl-build.log; tail -45 /tmp/valkey-acl-regression-after.log; exit "$result"

